// JARVIS #63 / #94 checks for this API, fully offline: the Stripe client is
// replaced by a stub before any request, keys are placeholders, and the app
// is bound to an ephemeral localhost port.
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { createRequire } from 'node:module';

process.env.DIVINATION_API_NO_LISTEN = '1';
process.env.STRIPE_SECRET_KEY = 'sk_test_placeholder_offline';
process.env.STRIPE_WEBHOOK_SECRET = 'whsec_placeholder_offline';
process.env.ANTHROPIC_API_KEY = 'placeholder-offline';
process.env.FRONTEND_URL = 'https://frontend.invalid';

const require = createRequire(import.meta.url);
const pricing = require('../src/pricing.json');
const CASES = {
  "product": "dreams",
  "typeField": "readingType",
  "metadataKey": "analysisType",
  "singleType": "dream-analysis",
  "readings": []
};

const { default: app, stripeService } = await import('../src/server.js');

const calls = [];
stripeService.stripe = {
  checkout: {
    sessions: {
      create: async (params) => { calls.push(params); return { id: 'cs_test_offline', url: 'https://checkout.invalid/cs_test_offline' }; },
      retrieve: async () => { throw new Error('offline test: no Stripe calls'); },
      update: async () => { throw new Error('offline test: no Stripe calls'); }
    }
  },
  events: { retrieve: async () => { throw new Error('offline test: no Stripe calls'); } },
  webhooks: { constructEvent: () => { throw new Error('offline test: no Stripe calls'); } }
};

let server, base;
before(async () => {
  server = app.listen(0, '127.0.0.1');
  await new Promise(r => server.once('listening', r));
  base = `http://127.0.0.1:${server.address().port}`;
});
after(() => new Promise(r => server.close(r)));

async function post(path, body) {
  const res = await fetch(base + path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body)
  });
  return { status: res.status, body: await res.json() };
}

function checkout(type) {
  const body = { email: 'buyer@example.invalid' };
  if (type !== undefined) body[CASES.typeField] = type;
  return post('/api/payment/create-checkout', body);
}

test('pricing.json has the expected product and only positive integer cents', () => {
  assert.equal(pricing.product, CASES.product);
  assert.ok(Object.keys(pricing.types).length > 0);
  for (const [type, e] of Object.entries(pricing.types)) {
    assert.ok(Number.isInteger(e.amount_cents) && e.amount_cents > 0, type);
  }
});

test('JARVIS #63 ladder: non-flagged types are $5 single or $10 deep', () => {
  for (const [type, e] of Object.entries(pricing.types)) {
    if (e.needs_principal) continue;
    assert.ok([500, 1000].includes(e.amount_cents), `${type} = ${e.amount_cents}`);
  }
  assert.equal(pricing.types[CASES.singleType].amount_cents, 500);
});

for (const type of Object.keys(pricing.types)) {
  test(`create-checkout charges the configured amount for "${type}" with promo codes on`, async () => {
    calls.length = 0;
    const res = await checkout(type);
    assert.equal(res.status, 200, JSON.stringify(res.body));
    assert.equal(res.body.amount_cents, pricing.types[type].amount_cents);
    assert.equal(calls.length, 1);
    const params = calls[0];
    assert.equal(params.line_items[0].price_data.unit_amount, pricing.types[type].amount_cents);
    assert.equal(params.allow_promotion_codes, true);
    assert.equal(params.mode, 'payment');
    assert.equal(params.metadata[CASES.metadataKey], type);
  });
}

for (const bad of ['nope', '', '__proto__', 'constructor', 'toString', 42, null]) {
  test(`create-checkout rejects unknown type ${JSON.stringify(bad)} with 400 and no Stripe call`, async () => {
    calls.length = 0;
    const res = await checkout(bad);
    assert.equal(res.status, 400);
    assert.equal(res.body.success, false);
    assert.equal(calls.length, 0);
  });
}

test('create-checkout with no type is 400 (no default price)', async () => {
  calls.length = 0;
  const res = await checkout(undefined);
  assert.equal(res.status, 400);
  assert.equal(calls.length, 0);
});

test('StripeService refuses a non-integer amount', async () => {
  calls.length = 0;
  const r = await stripeService.createCheckoutSession({ productName: 'x', description: 'x', amountCents: 4.99, email: 'a@b.invalid' });
  assert.equal(r.success, false);
  assert.equal(calls.length, 0);
});

for (const r of CASES.readings) {
  test(`JARVIS #94: ${r.path} without a paid session is 402 (paid from first use)`, async () => {
    const res = await post(r.path, r.body);
    assert.equal(res.status, 402, JSON.stringify(res.body));
    assert.equal(res.body.success, false);
  });
}
